-- 2. damage_exp3 below 80: Cataclysm creatures at old-world levels hit like the Wrath ones
UPDATE creature_classlevelstats SET damage_exp3 = damage_exp2 WHERE damage_exp3 = 0 AND level < 80;

-- 3. Above 85, the pre-MoP columns keep their level 85 value (Cataclysm's level 86-88 heroic elites)
UPDATE creature_classlevelstats c
JOIN creature_classlevelstats c85 ON c85.class = c.class AND c85.level = 85
SET c.damage_base = IF(c.damage_base = 0, c85.damage_base, c.damage_base),
    c.damage_exp1 = IF(c.damage_exp1 = 0, c85.damage_exp1, c.damage_exp1),
    c.damage_exp2 = IF(c.damage_exp2 = 0, c85.damage_exp2, c.damage_exp2),
    c.damage_exp3 = IF(c.damage_exp3 = 0, c85.damage_exp3, c.damage_exp3)
WHERE c.level > 85;
